styles:
.material-symbols-outlined {
    font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 24;
    font-size: 20px;
}
body {
    background-color: #fbf9f8;
    color: #1b1c1c;
    overflow-x: hidden;
}
.editorial-image-container {
    position: relative;
    overflow: hidden;
}
.editorial-image-container::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, rgba(251, 249, 248, 0.4), rgba(251, 249, 248, 0.1));
}
